"""Todo API: an in-memory list of to-do items."""

import itertools

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="Todo app")
items: dict[int, dict] = {}
_ids = itertools.count(1)


class NewItem(BaseModel):
    title: str


@app.post("/items", status_code=201)
def create_item(body: NewItem) -> dict:
    if not body.title.strip():
        raise HTTPException(422, "title must not be empty")
    item = {"id": next(_ids), "title": body.title.strip(), "done": False}
    items[item["id"]] = item
    return item


@app.get("/items")
def list_items(status: str | None = None) -> list[dict]:
    if status is None:
        return list(items.values())
    if status not in ("open", "done"):
        raise HTTPException(422, "status must be open or done")
    return [i for i in items.values() if i["done"] == (status == "done")]


@app.post("/items/{item_id}/complete")
def complete_item(item_id: int) -> dict:
    item = items.get(item_id)
    if item is None:
        raise HTTPException(404, "item not found")
    item["done"] = True
    return item


@app.delete("/items/{item_id}")
def delete_item(item_id: int) -> dict:
    if item_id not in items:
        raise HTTPException(404, "item not found")
    del items[item_id]
    return {"deleted": item_id}


class ItemUpdate(BaseModel):
    title: str


@app.patch("/items/{item_id}")
def edit_item(item_id: int, body: ItemUpdate) -> dict:
    item = items.get(item_id)
    if item is None:
        raise HTTPException(404, "item not found")
    if not body.title.strip():
        raise HTTPException(422, "title must not be empty")
    item["title"] = body.title.strip()
    return item
